(()=>{'use strict';window.installV8UI=function(e){
const $=id=>document.getElementById(id),P=RunePages,trees={PRECISION:'精密',DOMINATION:'主宰',SORCERY:'巫术',RESOLVE:'坚决',INSPIRATION:'启迪'},escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let draft;
let holdTimer=null;function hideRuneDetail(){clearTimeout(holdTimer);$('runeDescription').classList.add('hidden')}function bindRuneHold(button){let held=false,start=null;button.addEventListener('pointerdown',event=>{held=false;start={x:event.clientX,y:event.clientY};clearTimeout(holdTimer);holdTimer=setTimeout(()=>{held=true;let panel=$('runeDescription');panel.innerHTML='<b>'+escape(button.dataset.runeName)+'</b><p>'+escape(button.dataset.runeDescription)+'</p>';panel.classList.remove('hidden')},450)});button.addEventListener('pointermove',event=>{if(start&&Math.hypot(event.clientX-start.x,event.clientY-start.y)>12)hideRuneDetail()});for(let type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>{hideRuneDetail();start=null});button.addEventListener('contextmenu',event=>event.preventDefault());let select=button.onclick;button.onclick=event=>{if(held){held=false;event.preventDefault();return}select(event)}}function open(){draft=P.forHero(e.hero());render();$('runeEditor').classList.remove('hidden')}
function defaults(){let rows=(tree,row)=>RuneCatalog.all().filter(r=>r.tree===tree&&r.row===row).map(r=>r.key);draft.keystone=rows(draft.primary,0)[0];draft.main=[1,2,3].map(row=>rows(draft.primary,row)[0]);draft.minor=[rows(draft.secondary,1)[0],rows(draft.secondary,2)[0]]}
function render(){hideRuneDetail();let pages=P.list();$('runePageList').innerHTML='<option value="">英雄推荐页</option>'+pages.map(p=>'<option value="'+p.id+'">'+escape(p.name)+'</option>').join('');$('runePageList').value=draft.id||'';$('runePageName').value=draft.name;
for(let field of ['primary','secondary']){$('rune'+field).innerHTML=Object.entries(trees).map(([key,name])=>'<option value="'+key+'">'+name+'</option>').join('');$('rune'+field).value=draft[field]}
const describe=r=>r.description.replace('@HealAmount@',(r.numbers.healByLevel?.[0]||6)+'–'+(r.numbers.rawTooltipMax||23)+'（随等级）').replace('@BaseHeal@',(r.numbers.heal||[10,20]).join('–')).replace('@f3@',String(r.numbers.initialCooldown||270));const button=(r,selected)=>'<button type="button" data-rune="'+r.key+'" data-rune-name="'+escape(r.name)+'" data-rune-description="'+escape(describe(r))+'" class="'+(selected?'active':'')+'" aria-pressed="'+selected+'" aria-label="'+escape(r.name)+'"><img src="assets/runes/'+r.key+'.png" alt="" draggable="false"><span>'+escape(r.name)+'</span></button>';
$('runeMain').innerHTML=[0,1,2,3].map(row=>'<div class="rune-row">'+RuneCatalog.all().filter(r=>r.tree===draft.primary&&r.row===row).map(r=>button(r,row===0?draft.keystone===r.key:draft.main[row-1]===r.key)).join('')+'</div>').join('');
$('runeMinor').innerHTML=[1,2,3].map(row=>'<div class="rune-row">'+RuneCatalog.all().filter(r=>r.tree===draft.secondary&&r.row===row).map(r=>button(r,draft.minor.includes(r.key))).join('')+'</div>').join('');
let shardIcons={adaptive:'AdaptiveForce',attackSpeed:'AttackSpeed',haste:'CDRScaling',moveSpeed:'MovementSpeed',scalingHealth:'HealthScaling',health:'HealthPlus',tenacity:'Tenacity'};let labels={adaptive:'适应之力 +9AP / 5.4AD',attackSpeed:'攻速 +10%',haste:'技能急速 +8',moveSpeed:'移速 +2.5%',scalingHealth:'成长生命 10–200',health:'生命 +65',tenacity:'韧性与减速抗性 +15%'};$('runeShards').innerHTML=RuneCatalog.shards.map((row,i)=>'<div class="rune-row">'+row.map(key=>'<button data-shard="'+key+'" data-row="'+i+'" data-rune-name="属性碎片" data-rune-description="'+escape(JSON.stringify(RUNE_DATA_V8.shards[i].find(s=>(s.key==='healthScaling'?'scalingHealth':s.key)===key)))+'" aria-label="'+labels[key]+'" class="'+(draft.shards[i]===key?'active':'')+'"><img src="assets/runes/StatMods'+shardIcons[key]+'Icon.png" alt="" draggable="false"><span>'+labels[key].split(' ')[0]+'</span></button>').join('')+'</div>').join('');
document.querySelectorAll('[data-rune]').forEach(b=>b.onclick=()=>{let r=RuneCatalog.all().find(r=>r.key===b.dataset.rune);if(r.tree===draft.primary){if(r.row===0)draft.keystone=r.key;else draft.main[r.row-1]=r.key}else{let old=draft.minor.findIndex(key=>RuneCatalog.all().find(r=>r.key===key)?.row===r.row);if(old>=0)draft.minor[old]=r.key;else draft.minor=[draft.minor.at(-1),r.key]}render()});document.querySelectorAll('[data-shard]').forEach(b=>b.onclick=()=>{draft.shards[+b.dataset.row]=b.dataset.shard;render()});document.querySelectorAll('[data-rune-description]').forEach(bindRuneHold);
}
$('runeOpen').onclick=open;$('runeClose').onclick=()=>{hideRuneDetail();$('runeEditor').classList.add('hidden')};$('runePageList').onchange=()=>{draft=P.list().find(p=>p.id===$('runePageList').value)||P.recommended(e.hero());render()};$('runePageName').oninput=()=>draft.name=$('runePageName').value;
for(let field of ['primary','secondary'])$('rune'+field).onchange=()=>{draft[field]=$('rune'+field).value;if(draft.primary===draft.secondary)draft[field==='primary'?'secondary':'primary']=Object.keys(trees).find(k=>k!==draft[field]);defaults();render()};
$('runeSave').onclick=()=>{draft.name=$('runePageName').value;let result=P.save(draft);if(!result.ok){e.toast(result.errors.join('；'));return}draft=result.page;P.setDefault(e.hero(),draft.id);render();e.toast('符文已保存，并设为当前英雄默认页')};$('runeCopy').onclick=()=>{let result=P.create({...draft,name:draft.name+' 副本'});if(result.ok){draft=result.page;render()}};$('runeDelete').onclick=()=>{if(draft.id)P.delete(draft.id);draft=P.recommended(e.hero());render()};
$('cameraReset').onclick=()=>e.center();$('wardBtn').onclick=()=>{let u=e.player();if(!e.runes().placeWard(u,{x:u.x+Math.cos(u.angle)*200,y:u.y+Math.sin(u.angle)*200}))e.toast('守卫尚未就绪')};$('hexflashBtn').onclick=()=>{let u=e.player();if(!e.runes().castHexflash(u,{x:u.x+Math.cos(u.angle)*200,y:u.y+Math.sin(u.angle)*200}))e.toast('海克斯闪现尚不可用')};
$('runeToolsBtn').onclick=()=>{$('runeTools').classList.toggle('hidden');renderTools()};function renderTools(){let u=e.player(),r=e.runes();$('consumableList').innerHTML=r.consumables(u).map(c=>'<div><span>'+escape(c.id)+'</span><button data-consume="'+c.uid+'">使用</button><button data-consume-sell="'+c.uid+'">出售</button></div>').join('')||'<p>暂无消耗品</p>';document.querySelectorAll('[data-consume]').forEach(b=>b.onclick=()=>{r.useConsumable(u,b.dataset.consume);renderTools()});document.querySelectorAll('[data-consume-sell]').forEach(b=>b.onclick=()=>{if(e.canShop())r.sellConsumable(u,b.dataset.consumeSell);else e.toast('请在泉水出售');renderTools()});$('swapSpell').innerHTML=Object.entries(SUMMONER_CONFIG).map(([id,s])=>'<option value="'+id+'">'+s.name+'</option>').join('')}
$('buyPotion').onclick=()=>{if(e.canShop())e.runes().buyPotion(e.player());else e.toast('请在泉水购买');renderTools()};$('swapSpellBtn').onclick=()=>{if(!e.runes().swapSummoner(e.player(),+$('swapSlot').value,$('swapSpell').value))e.toast('启封秘籍尚未就绪，或技能不符合替换条件');else e.toast('召唤师技能已临时替换')};
};})();
